llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C04"],
      "claim": "Vismodegib, which shares the methylsulfonylphenyl and chloroheteroaryl motif, had a mean absolute oral bioavailability of 31.8% after a single 150 mg oral dose in healthy postmenopausal female subjects, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Rofecoxib, a methylsulfonylphenyl-containing drug, showed approximately 93% absolute oral bioavailability in humans at doses of 12.5–50 mg, strongly supporting high oral bioavailability for the query's methylsulfonylphenyl core.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C38"],
      "claim": "Valdecoxib, another methylsulfonylphenyl drug, had an absolute oral bioavailability of 83% in humans, supporting high F for this structural class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Esaxerenone, a methylsulfonyl-containing drug, had absolute oral bioavailability of 89.0% fasting and 90.8% postprandial in healthy Japanese subjects, supporting high F for sulfonyl-bearing lipophilic drugs.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C35"],
      "claim": "Celecoxib, a poorly water-soluble heteroaryl sulfonamide, still achieved oral bioavailability of 20–40% in humans, indicating that solubility limitations do not necessarily drive F below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "The active metabolite 6-MNA had a mean absolute bioavailability of 38% in healthy subjects, providing additional support that lipophilic heteroaryl systems can exceed the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C30"],
      "claim": "5-Hydroxyrofecoxib, a more polar hydroxylated metabolite of rofecoxib, had low oral bioavailability (~14.9%) in humans; this is the main contradictory example, but its lower transferability and extra polar/lactol functionality limit its relevance to the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a lipophilic, neutral methylsulfonylphenyl-biaryl with no obvious absorption liabilities. Multiple structurally related drugs with the same methylsulfonylphenyl/heteroaryl motif—vismodegib (31.8%), rofecoxib (93%), valdecoxib (83%), esaxerenone (~90%), and celecoxib (20–40%)—show absolute oral bioavailability at or above 20% in humans. The only low-F analogue is a more polar hydroxylated metabolite with lower transferability. Overall, the transferable experimental evidence supports F ≥ 20%.",
  "evidence_gaps": [
    "No direct experimental bioavailability data exist for the query molecule; all evidence comes from analogues with Morgan similarity ≤ 0.28.",
    "No human PK data are available for the exact methylpyridine-chloropyridine substitution pattern.",
    "No solubility or metabolic stability data are available for the query; high logD could affect formulation but does not necessarily determine F.",
    "Vismodegib shows saturable absorption, so dose-dependent bioavailability could vary in related compounds."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

